INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(494, 'koKR', 'Czas uderzyć', 'Milcz i słuchaj uważnie, $N.$b$bZostałam wysłana na tę pozycję, by obserwować miasteczko Międzygórze. Moja misja to zwiad. Musisz natychmiast przekazać wiadomość najwyższej egzekutorce Darthalii w Smolnym Młynie. Powiedz jej, że ja, tropicielka śmierci Lesh, przesyłam następujące słowa:$b$b„Kruczy krzyk z zachodu wzywa”.$b$bIdź drogą na wschód i uważnie patrz na drogowskazy. A teraz pospiesz się! Ruszaj do Smolnego Młyna, i to migiem, dodam!', 'Udaj się do Smolnego Młyna i przekaż wiadomość tropicielki śmierci Lesh najwyższej egzekutorce Darthalii.', '', '', '', '', '', '', 0),
(496, 'koKR', 'Eliksir męki', 'Ach, kolejny parszywy dzień w Smolnym Młynie. Całe to czyste powietrze wprawia mnie w taki podły nastrój, $N.$b$bIm prędzej zarazimy tutejszych ludzi, tym lepiej. Prowadzę intensywne badania nad substancjami zabójczymi, których mógłbym użyć w swoich miksturach, ale nie mam czasu, by je wszystkie zebrać.$b$bJeśli chcesz się na coś przydać, zdobądź dla mnie następujące rzeczy: 10 języków szarego niedźwiedzia i bardzo rzadką, trudną do znalezienia posokę pełzacza. Zarówno niedźwiedzie, jak i pełzacze znajdziesz tuż za Smolnym Młynem.', 'Aptekarz Lydon ze Smolnego Młyna chce 10 języków szarego niedźwiedzia i trochę posoki pełzacza.', '', '', '', '', '', '', 0),
(498, 'koKR', 'Na ratunek', 'Wódz wysłał mnie i kilku innych wojowników, żebyśmy odzyskali pewien przedmiot z Durnhold i zbadali ten cały Syndykat.$b$bPoszliśmy do Durnhold się rozejrzeć, ale zaskoczyła nas spora gromada ludzi. Walczyliśmy dzielnie, ale sama ich liczba wystarczyła, żeby nas pokonać. Kilku z nas wzięli do niewoli, ale mnie udało się uciec.$b$bDurnhold leży na południowy wschód stąd, za rzeką. Trzymają tam Drulla i Tog\'thara – musisz iść i ich uwolnić.', 'Krusk w Smolnym Młynie chce, żebyś $guwolnił:uwolniła; Drulla i Tog\'thara z Twierdzy Durnhold.', '', 'Wróć do Kruska w Smolnym Młynie w Międzygórzu.', 'Uwolnij Drulla', 'Uwolnij Tog\'thara', '', '', 0),
(499, 'koKR', 'Eliksir męki', 'Zmieszanie tych składników w coś, co nazwałem eliksirem męki, zajmie mi tylko chwilę.$b$bGotowe! Ach, nic tak nie rozjaśnia ponurego dnia na tym nędznym pogórzu jak wniesienie do świata odrobiny cierpienia.$b$bSprawdźmy, czy nasza mała mikstura działa tak, jak powinna.$b$bDaj mojemu asystentowi Umpiemu zakosztować tego, co Mroczna Pani szykuje zarówno ludziom, jak i Pladze.', 'Daj Umpiemu eliksir męki.', '', '', '', '', '', '', 0),
(500, 'koKR', 'Nagroda za ogry Kruszących Grań', 'Ogry Kruszących Grań wykopały sobie ogrzy kopiec wysoko w Górach Alterak, w pobliżu zrujnowanego miasta Alterak. A moi zwiadowcy donoszą, że zajęły też same ruiny.$B$BNie możemy pozwolić, żeby się tam zadomowiły. Jeśli uznają, że są tam bezpieczne, następnym krokiem będzie zejście na pogórze, a wtedy staną nam pod samymi drzwiami!$B$BIdź na północ, w Góry Alterak, i poluj na ogry. Przynieś mi brudne kostki, które noszą przy sobie, a zasłużysz na sowitą nagrodę.', 'Zbierz 9 brudnych kostek od ogrów Kruszących Grań w Górach Alterak. Zanieś je marszałkowi Redpathowi w Południowym Brzegu.', '', 'Wróć do marszałka Redpatha w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(501, 'koKR', 'Eliksir bólu', 'Och, $N... w Międzygórzu kwitną kwiaty, a powietrze jest takie świeże i rześkie. Nie mogę się powstrzymać, by nie pławić się w tej całej udręce. Wyglądam przez moje brudne okno i tęsknię za dniem, w którym nasza Nowa Zaraza przyniesie temu światu śmierć, na jaką zasługuje.$b$bChoć z przyjemnością siedziałbym i dumał ponuro przez cały dzień, wzywa mnie obowiązek wobec Mrocznej Pani. Pomożesz mi? Moje badania każą mi sądzić, że z krwi lwa górskiego zdołam przyrządzić najwspanialszy śmiercionośny wywar. Przynieś mi jej trochę, a zabawimy się.', 'Przynieś 10 fiolek krwi lwa górskiego aptekarzowi Lydonowi w Smolnym Młynie.', '', '', '', '', '', '', 0),
(502, 'koKR', 'Eliksir bólu', 'Ach, nie ma to jak zapach świeżej krwi na pogórzu!$b$bTeraz dodamy szczyptę tego i odrobinę tamtego, i niech zacznie się prawdziwa zabawa! To, co stworzyłem z tej krwi, lubię nazywać eliksirem bólu. Jeśli moje obliczenia są trafne, ta mikstura może być początkiem czegoś bardzo pięknego dla lady Sylwany. Ale potrzebujemy próby.$b$bZanieś ten eliksir na północną farmę na Polach Międzygórza, na południowym zachodzie. Zobaczmy, jak Stanleyowi, pieskowi rolnika Raya, posmakuje ten „przysmak”.', 'Nakarm Stanleya eliksirem bólu.', '', '', '', '', '', '', 0),
(503, 'koKR', 'Gol\'dir', 'Z dokumentów, które $gzdobyłeś:zdobyłaś;, wynika, że Gol\'dir jest przetrzymywany w dużej bazie Syndykatu na północy, najpewniej w Górach Alterak. Jest w niewoli o wiele za długo i trzeba go uwolnić.', 'Uwolnij Gol\'dira, a następnie wróć do Kruska w Smolnym Młynie.', 'Znajdź miejsce, w którym przetrzymywany jest Gol\'dir', 'Wróć do Gol\'dira na Wyżynie w Górach Alterak.', '', '', '', '', 0),
(504, 'koKR', 'Podżegacze Kruszących Grań', 'Skoro już $gposmakowałeś:posmakowałaś; walki z ogrami Kruszących Grań, chcę, żebyś porządnie im $gprzetrącił:przetrąciła; nosy...$B$BWejdź do Ruin Alterak i odszukaj podżegaczy Kruszących Grań. Chcę, żebyś $gwyciął:wycięła; ich sporą liczbę – tylko tak te bydlaki nauczą się trzymać z dala od ziem Przymierza.', 'Zabij 10 podżegaczy Kruszących Grań, a następnie wróć do marszałka Redpatha w Południowym Brzegu.', '', 'Wróć do marszałka Redpatha w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(505, 'koKR', 'Zabójcy z Syndykatu', 'Jestem nowym sędzią Południowego Brzegu. Mianowano mnie niedawno, po zamachu na mojego poprzednika. Zabójców nigdy nie odnaleziono, ale nasze śledztwo daje niemal pewność, że wynajął ich Syndykat – banda złodziei, którą przewodzą nikczemni szlachcice z upadłego już królestwa Alterak.$B$BSyndykat ma obozy na Przylądku Sofery i w Sztylecie Corahna, na północ i zachód od zajętego przez Hordę Smolnego Młyna. Zabijaj członków Syndykatu, których znajdziesz w tych obozach.', 'Zabij 12 zbójów Syndykatu i 8 złodziei Syndykatu, a następnie wróć do sędziego Henry\'ego Maleba w Południowym Brzegu.', '', 'Wróć do sędziego Henry\'ego Maleba w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(506, 'koKR', 'Dziedzictwo Blackmoore\'a', 'Dzień czy dwa temu odwiedził mnie przywódca tego Syndykatu. Nazywał się Aliden Perenolde i tytułował się panem tej ziemi. Zwierzył mi się ze swoich planów: chce zrobić niewolników z orków, którzy mu się przeciwstawili, tak jak planowali jego ojciec i jego mentor, znienawidzony Blackmoore.$b$bWażniejsze jest to, że przyprowadził ze sobą swoją kochankę, wiotką dziewczynę imieniem Elysa. Na szyi nosiła naszyjnik, którego pragnie wódz.$b$bA teraz idź. Sam znajdę drogę, gdy tylko załatwię tu swoje sprawy.', 'Przekaż informacje zebrane przez Gol\'dira Kruskowi w Smolnym Młynie.', '', '', '', '', '', '', 0),
(507, 'koKR', 'Lord Aliden Perenolde', 'Jasne jest, że Perenolde musi zginąć, a jego plugastwo musi zniknąć ze świata. Jego dwór leży kawałek na północ stąd, nad brzegiem Jeziora Lordamere. Wypełnij swój obowiązek, $N, a potem zdobądź naszyjnik, którego pragnie wódz, i wróć tutaj.', 'Zabij lorda Alidena Perenolde\'a i zapytaj jego kochankę, Elysę, o naszyjnik Tarethy.', '', 'Wróć do Elysy na Wyżynie w Górach Alterak.', '', '', '', '', 0),
(508, 'koKR', 'Dar Tarethy', 'Wisior? Oczywiście, możesz go wziąć... Weź go! Nie chcę żadnej pamiątki po nim... tylko proszę, proszę, odejdź w pokoju...', 'Zanieś naszyjnik Tarethy Kruskowi w Smolnym Młynie w Międzygórzu.', '', '', '', '', '', '', 0),
(509, 'koKR', '', 'Kolejny dzień, kolejny eliksir do przyrządzenia. Gdyby to zależało ode mnie, pozwoliłbym żałosnym ludziom i Pladze po prostu wybić się nawzajem. I tak wydają się do tego zdeterminowani.$b$bNiestety, nasza Mroczna Pani chce nieco przyspieszyć ten proces, więc czemu nie umilić sobie tych ponurych dni, szerząc po kraju odrobinę śmierci i chorób?$b$bOto plan, $N: udasz się do Zagrody Nethandera, na południe od Smolnego Młyna i na wschód od rzeki i Południowego Brzegu. Zbierz dla mnie z pola 6 kwiatów błotopyska do mojego następnego eliksiru.', 'Przynieś 6 kwiatów błotopyska aptekarzowi Lydonowi w Smolnym Młynie.', '', '', '', '', '', '', 0),
(510, 'koKR', 'Złowieszcze plany', 'Wśród tych dokumentów znajduje się lista zamówionych zapasów. Obejmuje zwykłe rzeczy (żywność, broń, odzież), ale też bardziej egzotyczny ekwipunek (maski, olej, truciznę).$B$BNajbardziej jednak uderza pilność zamówienia – zapasy były potrzebne szybko, by przeprowadzić coś, co dokument określa jako „ważną misję przeciwko Południowemu Brzegowi”.', 'Zanieś złowieszcze plany sędziemu Malebowi w Południowym Brzegu.', '', '', '', '', '', '', 0),
(511, 'koKR', '', 'Jeden z listów na tym stole jest zaszyfrowany i nie sposób go odczytać.', 'Zanieś zaszyfrowany list mistrzowi wiedzy Dibbsowi w Południowym Brzegu.', '', '', '', '', '', '', 0),
(512, 'koKR', 'Śmierć szlachcie', 'Obawiam się, że przywódcy Syndykatu dążą do zguby Południowego Brzegu. Musimy uderzyć w nich mocno, zanim ich plany się ziszczą.$B$BWejdź do ruin Strahnbradu, w Górach Alterak na północy. Sądzimy, że Syndykat urządził tam sobie kwaterę główną.$B$BWiemy, że tą bandą rzezimieszków kierują dawni szlachcice z Alterak. Mogą się ukrywać pośród zwykłych agentów Syndykatu, ale poznasz, że $gzabiłeś:zabiłaś; szlachcica, po sygnecie, który nosi.$B$BPrzynieś mi te sygnety.', 'Przynieś 7 sygnetów Alterak sędziemu Malebowi w Południowym Brzegu.', '', 'Wróć do sędziego Henry\'ego Maleba w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(517, 'koKR', '', 'Nowy eliksir jest wreszcie gotowy do próby. Ale po co marnować doskonałą, wysoce zakaźną zarazę na zwykłą żabę czy psa? Zabawmy się naprawdę w imię lady Sylwany.$b$bUdaj się do Dun Garok. Wiesz, do tych koszar, po których kręcą się te plugawe małe krasnoludy. Ukradnij mi beczkę ich stouta Shindiggera. Kiedy już ją dostanę, urządzimy sobie niezłą imprezę, $N.', 'Przynieś beczkę stouta Shindiggera aptekarzowi Lydonowi w Smolnym Młynie.', '', '', '', '', '', '', 0),
(518, 'koKR', '', 'Mug\'Thol i jego ogry Kruszących Grań opanowali ruiny Alterak. Trudno będzie wymierzyć mu jakąkolwiek poważną karę, jeśli najpierw nie przerzedzimy szeregów ogrów.$b$bGdy ich osłabimy, przejdziemy dalej.$b$bZrozumiano? Dobrze. A teraz idź.', 'Zabij 10 mocarzy Kruszących Grań dla Melisary w Smolnym Młynie.', '', 'Wróć do Melisary w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(519, 'koKR', '', 'Targ, Błotograb i Glommus to zastępcy Mug\'Thola. Są mu wierni, choć kto wie, co skłania ogra do lojalności.$b$bPrzynieś mi ich głowy, $N, a wtedy zostanie już tylko zdjąć głowę Mug\'Tholowi – razem z koroną.', 'Zabij Targa, Błotograba i Glommusa i przynieś ich głowy Melisarze w Smolnym Młynie.', '', 'Wróć do Melisary w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(520, 'koKR', '', 'Skoro zastępcy Mug\'Thola nie żyją, pozostało już tylko zabić Mug\'Thola i odzyskać Koronę woli. Nie wątpię, że niechętnie się z nią rozstanie. Pewnie też się ciebie spodziewa, zważywszy na... odejście... swoich kompanów.$b$bZnajdź Mug\'Thola i dostarcz mi jego głowę oraz koronę. Na tym skończy się opór Kruszących Grań.', 'Zabij Mug\'Thola i przynieś jego głowę wraz z Koroną woli Melisarze w Smolnym Młynie.', '', 'Wróć do Melisary w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(522, 'koKR', 'Kontrakt zabójcy', 'To kontrakt na zabójstwo sędziego Henry\'ego Maleba. Zapieczętowano go czerwonym woskiem, odciskając w nim charakterystyczny sygnet.', 'Zanieś kontrakt zabójcy sędziemu Malebowi w Południowym Brzegu.', '', '', '', '', '', '', 0),
(523, 'koKR', 'Upadek barona', 'Kontrakt, który $godzyskałeś:odzyskałaś;, podpisał baron Vardus, szlachcic z dawnego królestwa Alterak, znany z zimnego serca i brutalnych metod. Nie dziwi mnie, że ktoś taki jak baron za tym stoi.$B$BZnajdź tego człowieka. Znajdź go i wymierz mu sprawiedliwość. Musi przebywać w którejś z kryjówek Syndykatu – może w ruinach Strahnbradu, a może w dolinie na północ od nich.', 'Przynieś głowę barona Vardusa sędziemu Malebowi w Południowym Brzegu.', '', 'Wróć do sędziego Henry\'ego Maleba w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(524, 'koKR', '', 'W sąsiednim budynku strażnicy śmierci przetrzymują jako zakładników kilku pojmanych rolników. Najwyższa egzekutorka Darthalia podejrzewała, że ukrywa się wśród nich jeden ze strategów wojskowych z Wichrogrodu. Najwyraźniej tego wojskowego jegomościa znaleziono ostatniej nocy martwego na Plagowiskach. Darthalia, która zawsze o mnie dba, postanowiła oddać więźniów do mojej dyspozycji.$b$bMyślę, że czas urządzić tym rolnikom przyjęcie. Zapowiada się wyborna zabawa!$b$bPostaw tę skażoną beczkę na dywanie w ich izbie. Zadżumiony trunek dla wszystkich!', 'Postaw skażoną beczkę na dywanie dla pojmanych rolników.', '', '', '', '', '', '', 0),
(527, 'koKR', '', 'Baczność, kiedy się do mnie zwracasz, $N.$b$bPodlegam bezpośrednio Varimathrasowi. Mamy tępić ludzkie robactwo, dopóki nasi aptekarze nie opracują nowej zarazy.$b$bNasze informacje wskazują, że miasteczko Międzygórze jest podatne na atak. Twoje pierwsze zadanie ma zakłócić ich zaopatrzenie w żywność i infrastrukturę.$b$bIdź na zachód. Najedź najbardziej wysunięte na północ farmy na Polach Międzygórza. Dopilnuj też, by właściciele ziemi, rolnik Ray i rolnik Getz, zostali straceni.', 'Zabij 6 parobków z Międzygórza, 6 rolników z Międzygórza, rolnika Raya i rolnika Getza, a następnie zamelduj się u Darthalii w Smolnym Młynie.', '', 'Wróć do najwyższej egzekutorki Darthalii w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(528, 'koKR', '', 'Wieść o ataku na północne farmy wywołała panikę wśród mieszkańców. Doskonale.$b$bNasi tropiciele śmierci donoszą, że chłopi uciekają na pola w południowej części Międzygórza. Głupcy myślą, że skryją się w sadach i unikną zguby.$b$bWyprowadź ich z błędu, $N. Wróć na Pola Międzygórza i odszukaj kulących się ze strachu chłopów. Wytnij ich w imię naszej Mrocznej Pani.$b$bOdmaszerować!', 'Zabij 15 chłopów z Międzygórza i zamelduj się u Darthalii w Smolnym Młynie.', '', 'Wróć do najwyższej egzekutorki Darthalii w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(529, 'koKR', '', 'Ludzie z Międzygórza stawiają nieoczekiwany opór. Wygląda na to, że mieszkańców zbroi miejscowy kowal. Musimy odciąć wszystkie linie zaopatrzenia.$b$bTwoją misją będzie stracić kowala Verringtana. Zabij też jego uczniów. Przy okazji przynieś dostawę żelaza z ich składu. Zapasy przydadzą się, gdy skończymy podbijać Międzygórze i zaczniemy równać z ziemią Południowy Brzeg.', 'Zabij kowala Verringtana i 4 uczniów kowala z Międzygórza.$b$bZdobądź dostawę żelaza i zamelduj się u Darthalii w Smolnym Młynie.', '', 'Wróć do najwyższej egzekutorki Darthalii w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(532, 'koKR', '', 'Miasteczko Międzygórze pogrążyło się w chaosie i sądzimy, że wkrótce padnie. Musimy jednak trwać w bezwzględności, dopóki ludzkie szumowiny nie zostaną na zawsze wymazane z pogórza.$b$bMimo przytłaczających strat ludzie skupiają się wokół swoich przywódców i walczą dalej. Musimy wyeliminować ich przywódcę, sędziego Burnside\'a, a także radę miejską. Zniszcz też ich czczony dokument polityczny – Obwieszczenie Międzygórza. A przy okazji ukradnij rejestr miejski.', 'Zabij sędziego Burnside\'a i 4 rajców z Międzygórza. Zniszcz Obwieszczenie Międzygórza. Ukradnij rejestr miejski Międzygórza. Następnie zamelduj się u Darthalii w Smolnym Młynie.', '', 'Wróć do najwyższej egzekutorki Darthalii w Smolnym Młynie w Międzygórzu.', '', '', 'Obwieszczenie Międzygórza zniszczone', '', 0),
(533, 'koKR', 'Infiltracja', 'Wreszcie docierają do nas wieści i pogłoski, znajdujemy ślady tego, gdzie jest Gol\'dir. Ludzie przenosili go z miejsca na miejsce, ale zawężamy poszukiwania i skupiamy się na dużym obozie Syndykatu tuż na północ stąd.$b$bIdź tam, $N, i przynieś wszelkie informacje, jakie wpadną ci w ręce.', 'Zdobądź dla Kruska w Smolnym Młynie informacje o tym, gdzie przebywa Gol\'dir.', '', 'Wróć do Kruska w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(536, 'koKR', 'Wzdłuż wybrzeża', 'Przeniesiony ze straży miejskiej Wichrogrodu do Południowego Brzegu, miasteczka, które sądząc po wyglądzie, powinno się porzucić... Dzień i noc smród portu.$b$bNie wspominając o starym Redpathcie... Chce, żebym zajął się murlokami. Ha! $b$bLedwo potrafię się zebrać, żeby wybrać się do tych gniazd przerośniętych ryb w dół Zachodniego Wybrzeża. Jeśli pójdziesz tam za mnie i się nimi zajmiesz, będę wdzięczny.', 'Zabij 10 łowców fal Poszarpanopłetwych i 10 wyroczni Poszarpanopłetwych dla porucznika Farrena Orinelle\'a w Południowym Brzegu.', '', 'Wróć do porucznika Farrena Orinelle\'a w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(537, 'koKR', 'Mroczna rada', 'List, który mi $gprzyniosłeś:przyniosłaś;, napisał ktoś, kto nazywa siebie Nagazem – członek Czuwania Argusa. Nie wiem, czym jest to Czuwanie Argusa, ale jeśli sprzymierzyło się z Syndykatem, musi stanowić zagrożenie.$B$BChcę, żebyś $godnalazł:odnalazła; Nagaza i magów cienia Argusa, o których wspomina ten list. Chcę, żebyś ich $godnalazł:odnalazła; i $gzabił:zabiła;.$B$BSzukaj na Wyżynie, gdzie Syndykat jest najsilniejszy. Leży ona na północ od Strahnbradu.$B$BPrzy odrobinie szczęścia znajdziesz tam tych wysłanników Czuwania Argusa.', 'Zabij 4 magów cienia Argusa.$B$BPrzynieś głowę Nagaza sędziemu Malebowi w Południowym Brzegu.', '', 'Wróć do sędziego Henry\'ego Maleba w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(539, 'koKR', '', 'Rejestr miejski Międzygórza wskazuje, że Kopalnia Lazurowej Żyły jest pod kontrolą Przymierza. Co więcej, kopalnia jest głównym źródłem rudy żelaza dla zbrojowni Przymierza.$b$bChoć zadaliśmy miasteczku Międzygórze decydujący cios, Przymierze wciąż żarliwie wspiera i chroni Kopalnię Lazurowej Żyły.$b$bKopalnia leży dokładnie na południe od Międzygórza. Udaj się tam i zabij brygadzistę, człowieka nazwiskiem Bonds. Zabij też jego górników. To będzie dla Przymierza jasny sygnał.', 'Zabij brygadzistę Bondsa i 10 górników z Międzygórza, a następnie zamelduj się u Darthalii w Smolnym Młynie.', '', 'Wróć do najwyższej egzekutorki Darthalii w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(541, 'koKR', '', 'Krasnoludy pomagają ludziom? Niech szlag trafi te plugawe małe bestie.$b$bWystawimy na próbę siłę tak zwanego Przymierza. Zobaczymy, jak bardzo tym kurduplom będzie się spieszyć do pomocy ludziom, gdy poczują nasz gniew. Wiemy dokładnie, gdzie na tym terytorium mają twierdzę.$b$bZałożyli koszary zwane Dun Garok w południowo-wschodnim Międzygórzu, przy Murze Thoradina. Ostatnią misją tej bitwy jest oblężenie Dun Garok, $N. Ich przywódca, kapitan Żelaznogór, musi zginąć.', 'Udaj się do Dun Garok i zabij 8 górskich strażników, 4 strzelców, 2 kapłanów i kapitana Żelaznogóra, a następnie zamelduj się u Darthalii w Smolnym Młynie.', '', 'Wróć do najwyższej egzekutorki Darthalii w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(544, 'koKR', 'Włamanie do więzienia', 'Przybyłem do Smolnego Młyna prowadzić badania, a teraz muszę zażegnać kryzys. Widzisz, kilka miesięcy temu czterech Porzuconych uciekło z Podmiasta. Odwrócili się od swoich braci, ale co gorsza... okradli Mroczną Panią.$B$BCi złodzieje włamali się do strzeżonego skarbca i ukradli cztery artefakty – przedmioty, których nasi aptekarze potrzebowali do pewnych badań. Sylwana życzy sobie, by te artefakty zostały zwrócone.$B$BZłodzieje uciekli z Podmiasta do Dalaranu, a tamtejsi czarodzieje zamknęli ich w Obozie Internowania Lordamere.', 'Znajdź zdrajców i odzyskaj ich artefakty, a następnie wróć do maga Pustkowzroka w Smolnym Młynie.', '', 'Wróć do maga Wordeena Pustkowzroka w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(545, 'koKR', 'Patrole Dalaranu', 'Czarodzieje z Dalaranu wznieśli wokół serca swojego miasta ogromną magiczną kopułę. Jedni uważają, że miała chronić przed przemocą tych czasów, inni twierdzą, że czarodzieje chcieli po prostu samotności, by w spokoju studiować i knuć.$B$BNie obchodzi mnie, jaki był powód. Obchodzi mnie natomiast to, że zrujnowane obrzeża ich miasta mogą kryć cenne magiczne skarby.$B$BAle okolicę patrolują czarodzieje i ich zniewolone żywiołaki.$B$BPoluj więc na nich i wróć, gdy dostatecznie przerzedzisz ich szeregi.', 'Zabij 6 przywoływaczy z Dalaranu i 12 zniewolonych żywiołaków, a następnie wróć do maga Pustkowzroka w Smolnym Młynie.', '', 'Wróć do maga Wordeena Pustkowzroka w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(546, 'koKR', 'Pamiątki śmierci', 'Słyszałem, że Darthalia zwerbowała cię do wojny z ludźmi z Międzygórza. Ależ ci zazdroszczę...$b$bPodczas gdy ty będziesz się świetnie bawić – zabijać ludzi, plądrować miasteczko, terroryzować niewinnych – ja tkwię na warcie tu, w Smolnym Młynie.$b$bMoże zlitujesz się nad starym strażnikiem śmierci takim jak ja? Widzisz, kolekcjonuję ludzkie czaszki. A ty jeszcze długo będziesz walczyć z ludźmi. W trakcie tej długiej walki przynieś mi 30 czaszek, a sowicie ci się odwdzięczę.', 'Strażnik śmierci Samsa ze Smolnego Młyna chce 30 ludzkich czaszek z Międzygórza.', '', 'Wróć do strażnika śmierci Samsy w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(547, 'koKR', 'Miecz Humberta', 'Najwyższa egzekutorka Darthalia wysłała mnie, bym z daleka obserwował Dun Garok. Rozbiłem obóz tuż poza zasięgiem ich wzroku. Ale gdy nadszedł ranek i trzeba było zagotować wodę, poszedłem nazbierać chrustu.$b$bKiedy wróciłem do obozu, okazało się, że mój ekwipunek zniknął.$b$bNajwyraźniej przechodzili tędy krasnoludzcy zwiadowcy z Dun Garok i go zwinęli. Potrzebuję mojego miecza! Jeśli zdołasz go odzyskać, będę ci bardzo wdzięczny. Tyle tam krasnoludów... trudno będzie znaleźć tego brudnego małego złodzieja, który go ukradł.', 'Odzyskaj miecz strażnika śmierci Humberta z Dun Garok i zwróć mu go w Smolnym Młynie.', '', 'Wróć do strażnika śmierci Humberta w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(549, 'koKR', 'POSZUKIWANI: członkowie Syndykatu', 'Z rozkazu lady Sylwany wszyscy członkowie organizacji znanej jako Syndykat mają zostać zgładzeni. Pojmani lub wzięci do niewoli zostaną straceni bez sądu. Wiadomo, że obecnie gromadzą się w ruinach Twierdzy Durnhold, na południowy wschód od Smolnego Młyna.$b$bSowita nagroda czeka na każdego, kto przedstawi dowody swoich czynów najwyższej egzekutorce Darthalii.', 'Zabij 10 łotrów Syndykatu i 10 stróżów Syndykatu. Po nagrodę zgłoś się do najwyższej egzekutorki Darthalii w Smolnym Młynie.', '', 'Wróć do najwyższej egzekutorki Darthalii w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(551, 'koKR', 'Zaczarowany pergamin', 'Ten pergamin jest zaczarowany, przez co nie da się go odczytać. Jedno słowo u góry kartki jest jednak czytelne:$B$B$B      Nagaz$B$B', 'Zanieś zaczarowany pergamin mistrzowi wiedzy Dibbsowi w Południowym Brzegu w Międzygórzu.', '', '', '', '', '', '', 0),
(552, 'koKR', 'Zemsta Helculara', 'Mistrz Helcular niemal dokończył przemianę w lisza, gdy żądny linczu tłum ludzi odkrył jego rytualną kryjówkę na wzgórzach i brutalnie go zamordował. Co gorsza, pochowali jego zwłoki na cmentarzu w Południowym Brzegu.$b$bTakie lekceważenie wielkiego czarodzieja jest nie do przyjęcia. Jako jego uczeń dopilnuję, by na Południowy Brzeg spadły deszcze zemsty.$b$bNajpierw będziemy potrzebować różdżki Helculara. Jego rytualną kryjówkę opanowały yeti. Bez wątpienia któraś z tych bestii ją ma.', 'Odbierz yeti różdżkę Helculara i przynieś ją nowicjuszowi Thaivandowi w Smolnym Młynie.', '', 'Wróć do nowicjusza Thaivanda w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(553, 'koKR', 'Zemsta Helculara', 'Proszę, weź różdżkę Helculara. Będzie ci potrzebna.$b$bHelcular przygotował 3 obrzędowe stosy jako część swojego najpotężniejszego zaklęcia. Płomień Azela i Płomień Veraza znajdują się w Pieczarach Pogórza. Płomień Uzela płonie w jaskini nad pieczarami, dalej na północ, w górach.$b$bRóżdżkę Helculara trzeba naładować mocą każdego z trzech płomieni. Gdy rytuał dobiegnie końca, wbij różdżkę w grób Helculara w Południowym Brzegu, silnie strzeżonym ludzkim miasteczku na południu. Zemsta będzie nasza!', 'Naładuj różdżkę Helculara mocą Płomienia Azela, Płomienia Veraza i Płomienia Uzela.$b$bWbij naładowaną różdżkę w grób Helculara w Południowym Brzegu.', '', 'Odszukaj grób Helculara na cmentarzu w Południowym Brzegu w Międzygórzu.', 'Naładowano mocą Płomienia Azela', 'Naładowano mocą Płomienia Veraza', 'Naładowano mocą Płomienia Uzela', '', 0),
(555, 'koKR', 'Kojący krem z żółwia', 'Jeśli jest coś, czego się dowiesz o Południowym Brzegu, to tego, że mamy jedną z najlepszych kuchni na północ od Wichrogrodu!$b$bWeźmy na przykład mój sekretny przepis na krem z żółwia. Znam ludzi, którzy przyjeżdżali aż z Mrocznych Włości, żeby zjeść miseczkę. À propos, ostatnio nie mogłem go przyrządzać. Kiedyś sam wyprawiałem się za Dalaran, nad Jezioro Lordamere, żeby polować na kłapacze, ale teraz jest tam po prostu zbyt niebezpiecznie. Jeśli przyniesiesz mi mięso żółwia z kłapaczy na północy, coś upichcę!', 'Przynieś 10 kawałków mięsa żółwia kucharzowi Jessenowi w Południowym Brzegu.', '', 'Wróć do kucharza Jessena w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(556, 'koKR', 'Kamienne żetony', 'Czarodzieje z Dalaranu słyną z obycia z żywiołakami: potężnymi istotami z innych wymiarów. Używają magicznych żetonów, by nad nimi panować. Mag Pustkowzrok chciałby zbadać kilka takich żetonów.$B$BWejdź na tereny dalarańskich czarodziejów, na zachód od Międzygórza, i zbierz żetony.$B$BMożesz je znaleźć przy każdym mieszkańcu Dalaranu, ale radzę polować w obozie internowania. Tam jest bezpieczniej niż w samym Dalaranie.', 'Przynieś 10 wytartych kamiennych żetonów opiekunowi Bel\'varilowi w Smolnym Młynie.', '', 'Wróć do opiekuna Bel\'varila w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(557, 'koKR', 'Karwasze więzi', 'Mag będzie zajęty badaniem kamiennych żetonów, które $gzebrałeś:zebrałaś;, ale wiem, że w końcu zechce też przykładów ich odpowiedników: karwaszy więzi. Zakłada się je na nadgarstki prawdziwych żywiołaków, co wiąże je ze służbą magowi.$B$BPoluj na żywiołaki w ruinach Dalaranu i zbierz ich karwasze więzi ziemi, a mag będzie zadowolony.', 'Przynieś 4 karwasze więzi ziemi opiekunowi Bel\'varilowi w Smolnym Młynie.', '', 'Wróć do opiekuna Bel\'varila w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(559, 'koKR', 'Dowód Farrena', 'Uwierzysz, $N? Redpathowi nie wystarczyły wszystkie murloki, które zabiliśmy – no nie, nie bądź $gskromny:skromna;, $gmiałeś:miałaś; w tym swój udział. Teraz chce, żebym przyniósł dowód ich śmierci: mam odrąbywać zimne, oślizgłe łby murloków i przedstawiać mu je do zatwierdzenia.', 'Zdobądź 10 głów murloków z Zachodniego Wybrzeża dla porucznika Farrena Orinelle\'a w Południowym Brzegu.', '', 'Wróć do porucznika Farrena Orinelle\'a w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(560, 'koKR', 'Dowód Farrena', 'Wiesz, $n, właściwie wolałbym nie brać tych głów... Skoro i tak już je masz, $gmógłbyś:mogłabyś; zanieść je za mnie Redpathowi?', 'Dostarcz worek głów murloków marszałkowi Redpathowi w Południowym Brzegu.', '', '', '', '', '', '', 0),
(561, 'koKR', 'Dowód Farrena', 'Przekaż, proszę, porucznikowi Orinelle\'owi, że chciałbym, by skupił swoje wysiłki na nagach, które opanowały Wschodnie Wybrzeże. Gdy osiągnie wyniki, niech zamelduje mi się osobiście.', 'Porozmawiaj z porucznikiem Farrenem Orinelle\'em w Południowym Brzegu.', '', '', '', '', '', '', 0),
(562, 'koKR', 'Kurs na Wichrogród!', 'Mój dawny mentor ze straży miejskiej Wichrogrodu przysłał mi wiadomość, że Naczelne Dowództwo Przymierza zaczyna się niepokoić zagrożeniem ze strony nag. Z tego, co słyszał, każdy, kto okaże się w tej sprawie przydatny, ma spore szanse na awans – albo przynajmniej na przeniesienie.$b$bJest tylko jeden mały problem... Nie poradzę sobie z nagami, $n. Jasne, mógłbym rozgonić pijacką bójkę w karczmie albo wywlec awanturującego się żebraka, ale nagi mnie przerastają. Musisz mi pomóc, $n!', 'Zabij 10 łowców brzegów Sztyletogrzbietych i 10 syren Sztyletogrzbietych dla porucznika Farrena Orinelle\'a w Południowym Brzegu.', '', 'Wróć do porucznika Farrena Orinelle\'a w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(564, 'koKR', 'Kosztowne utrapienie', 'Nic mnie tak nie wkurza jak tracenie tych tu pięknych koni. I wierz mi, straciliśmy ich sporo przez tych wstrętnych nieumarłych, cholerną bandę z Syndykatu i całą resztę nicponiów, co się kręcą po okolicy.$b$bAle przysięgam na grób mojego starego dziadka, że nie ma dla naszych koni większego zagrożenia niż te lwy górskie tam, w Górach Alterak. Ciągle schodzą ze wzgórz i uprzykrzają mi życie!$b$bUważasz się za $gbohatera:bohaterkę;? To idź i zrób coś z tym!', 'Darren Malvew z Południowego Brzegu chce, żebyś $gzabił:zabiła; 8 lwów górskich i 10 potężnych lwów górskich.', '', 'Wróć do Darrena Malvewa w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(565, 'koKR', 'Płaszcz z futra yeti od Bartola', 'Ja, wielki Bartolo, uszyję dla ciebie słynny na cały świat, sławny w całym Przymierzu Płaszcz z futra yeti!$b$bPrzemierz cały świat i znajdź lepszy płaszcz – no, śmiało. Och, chwileczkę, co mówisz, $gmaleńki przyjacielu:maleńka przyjaciółko;? „Bartolo, nie ma lepszego płaszcza!” Tak, tak! To już słyszałem.$b$bBartolo potrzebuje beli wełnianego płótna, płaszcza górala uszytego przez wprawnego garbarza, cienkiej nici i, rzecz jasna, futra yeti! Przynieś mi te rzeczy, a będziesz $gzadowolonym klientem:zadowoloną klientką;!', 'Przynieś Bartolowi Ginsettiemu z Południowego Brzegu belę wełnianego płótna, płaszcz górala, cienką nić i 10 kłębków futra yeti.', '', 'Wróć do Bartola Ginsettiego w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(566, 'koKR', 'POSZUKIWANY: baron Vardus', 'Z rozkazu najwyższej egzekutorki Darthalii człowiek znany jako baron Vardus jest poszukiwany za zbrodnie przeciwko Porzuconym. Wiadomo, że Vardus jest wysoko postawionym członkiem organizacji zwanej Syndykatem.$b$bOstatnio widziano go na Wyżynie w Górach Alterak, na północ od Smolnego Młyna.$b$bJest poszukiwany martwy. Dostarcz dowód jego śmierci najwyższej egzekutorce Darthalii, by odebrać nagrodę.', 'Zabij barona Vardusa i dostarcz jego głowę najwyższej egzekutorce Darthalii w Smolnym Młynie.', '', 'Wróć do najwyższej egzekutorki Darthalii w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(567, 'koKR', 'Niebezpieczeństwo!', 'Niebezpieczeństwo!$b$bNastępujący ludzie z Międzygórza zostali uznani za niebezpiecznych, a najwyższa egzekutorka Darthalia wyznaczyła nagrodę za ich głowy:$b$bUrzędnik Horrace Białorumak. Poszukiwany za zabójstwo strażnika śmierci Tomy.$b$bObywatel Wilkes. Poszukiwany za zabójstwo aptekarza Eliego.$b$bGórnik Hackett. Poszukiwany za zabójstwo tropiciela śmierci Fry\'a.$b$bFarmerka Kalaba. Poszukiwana za napad na dostawy z Podmiasta.$b$bWszyscy ci wrogowie się ukrywają i trudno będzie ich znaleźć. Nagroda zostanie wypłacona po otrzymaniu wieści o ich śmierci.', 'Najwyższa egzekutorka Darthalia ze Smolnego Młyna wyznaczyła nagrodę za urzędnika Horrace\'a Białorumaka, obywatela Wilkesa, górnika Hacketta i rolniczkę Kalabę.', '', 'Wróć do najwyższej egzekutorki Darthalii w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(657, 'koKR', 'Oznaki nowej zarazy?', '<Quae zaczyna przeglądać teczkę.>$B$BTo NAPRAWDĘ ciekawe. Wygląda na to, że aptekarz Jorell prowadzi tu, w Go\'Shek, jakieś śmiercionośne eksperymenty. Nie wiem, co to ma wspólnego z Międzygórzem, ale Phinowi by się nie spodobało, gdybyśmy pozwoliły mu to ciągnąć.$B$BPod twoją nieobecność starłyśmy się z orkami i nie jestem w dość dobrej formie, żeby pomóc Kinelory. Jeśli masz ochotę, przyda jej się ochrona, gdy zejdzie na farmę wykraść te wyniki badań, których Jorell nie zdążył jeszcze wysłać do Smolnego Młyna.', 'Porozmawiaj z Kinelory przy Farmie Go\'Shek na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(658, 'koKR', 'Oznaki nowej zarazy?', 'A więc Phin przysłał cię, żebyś $gsprawdził:sprawdziła;, co u nas? Nic dziwnego – za bardzo się martwi.$B$BObserwujemy farmę od kilku dni, a Kin twierdzi, że niedawno widziała kuriera wychodzącego z tego małego domku na południu.$B$BDużo gada, ale kiedy jesteśmy w niebezpiecznych miejscach, zawsze mogę polegać na jej zmysłach.$B$BUmiesz może dobrze tropić? Sądzimy, że kurier może nieść wiadomości do Smolnego Młyna. Gdybyśmy zdobyły te dokumenty, może rzuciłyby trochę światła na to, co się dzieje w Międzygórzu.', 'Odnajdź kurierkę Porzuconych i przynieś jej zapieczętowaną teczkę Quae przy Farmie Go\'Shek.', '', 'Wróć do Quae na Wyżynach Aratorskich.', '', '', '', '', 0),
(659, 'koKR', 'Oznaki nowej zarazy?', 'Witaj, $N, miło cię poznać. Przewodzę grupie poszukiwaczy przygód, która bada dziwne wydarzenia w tej okolicy.$B$BMój kuzyn z Międzygórza musiał niedawno uśpić swojego psa Stanleya, bo zwierzę w tajemniczy sposób urosło do ogromnych rozmiarów i dziko atakowało każdego, kto się do niego zbliżył.$B$BSądzę, że maczają w tym palce nieumarli, i szukamy śladów, które by to potwierdziły.$B$BDwie moje towarzyszki, Quae i Kinelory, wyruszyły na Farmę Go\'Shek na Wyżynach Aratorskich i od kilku dni nie dają znaku życia. Odnajdziesz je dla mnie? Zaczynam się niepokoić.', 'Odnajdź Quae i Kinelory przy Farmie Go\'Shek na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(660, 'koKR', 'Oznaki nowej zarazy?', 'No dobrze, $N. Jestem gotowa, jeśli ty też.$B$BIdziemy?', 'Chroń Kinelory, dopóki nie wróci do Quae.', 'Chroń Kinelory', 'Wróć do Quae na Wyżynach Aratorskich.', '', '', '', '', 0),
(661, 'koKR', 'Oznaki nowej zarazy?', 'Widywałam Kinelory w dużo gorszym stanie po nocy w tawernie. Najwyraźniej dobrze jej $gpilnowałeś:pilnowałaś;.$B$BTe rzeczy, które przyniosła z farmy, powinny przynajmniej dać Phinowi pojęcie o tym, co się dzieje tu, na Wyżynach Aratorskich. Żeby się upewnić, że po twoim ataku nie będzie odwetu, zostaniemy tu jeszcze trochę. $GWróciłbyś:Wróciłabyś; do Południowego Brzegu porozmawiać z Phinem?', 'Odnajdź Phina Odelica w Południowym Brzegu w Międzygórzu.', '', '', '', '', '', '', 0),
(676, 'koKR', 'Czy Młotogród upadnie?', 'Słabeusze... wszyscy co do jednego. Ty, $N, na co się gapisz? Myślisz, że jesteś kimś wyjątkowym, co? To czemu tego nie udowodnisz?$B$BPlacówka Młotogród na Wyżynach Aratorskich jest atakowana. Jeśli wkrótce nie wyślemy im pomocy, czeka ich zguba.$B$BAle zanim tam pognasz, może warto najpierw sprawdzić swoje umiejętności. Na północny wschód od Stromgardu jest kopiec ogrów zamieszkany przez plemię Głazopięści. Kiedy poradzisz sobie z tamtejszymi ogrami i egzekutorami, zamelduj się u Druma Fela w Młotogrodzie.', 'Zabij 8 ogrów Głazopięści i 10 egzekutorów Głazopięści, a następnie odnajdź Druma Fela w placówce Młotogród na Wyżynach Aratorskich.', '', 'Wróć do Druma Fela w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(1051, 'koKR', 'Zemsta Vorrela', 'Choć moja wola jest wolna, nie mogę już dłużej służyć Mrocznej Pani. Czuję, że mój czas w Azeroth dobiegł końca. Moja siła życiowa została strzaskana.$b$bTo śledczy Vishas mi to zrobił! Torturował mnie tygodniami! Zabrał moją obrączkę i dał ją swojej żonie. Potwór!$b$bZemsta... Pragnę zemsty!$b$bTen napuszony głupiec chełpił się swoją drogocenną żoną, Nancy, która mieszka nad Jeziorem Lordamere. Wytrop tę dziewuchę, zabij ją i zwróć moją obrączkę mojej żonie, Monice, w Smolnym Młynie.$b$bSpełnij moją ostatnią wolę...', 'Zwróć obrączkę Vorrela Sengutza Monice Sengutz w Smolnym Młynie.', '', 'Wróć do Moniki Sengutz w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(1052, 'koKR', 'Szkarłatną ścieżką', 'My, Szkarłatna Krucjata, mamy twierdze od Żagiewia po Polany Tirisfal. Jesteśmy bardzo dumni z naszych bastionów oczyszczenia w całym Lordaeronie.$b$b$GDowiodłeś:Dowiodłaś; swej wartości w walce z nieumarłymi w Mrocznym Pustkowiu. Ale prawdziwe zagrożenie zarazą czai się w Lordaeronie.$b$bUdaj się do miasta Południowy Brzeg we Wschodnich Królestwach. Odszukaj krzyżowca imieniem Raleigh Pobożny. Daj mu ten list polecający z moją pieczęcią, a on zaprowadzi cię na zaszczytne miejsce w naszym Szkarłatnym Klasztorze.', 'Zanieś list polecający brata Antona Raleighowi Pobożnemu w Południowym Brzegu.', '', '', '', '', '', '', 0),
(1053, 'koKR', 'W imię Światłości', 'Niegdyś służyłem Szkarłatnej Krucjacie z honorem, lojalnością i dumą. Wierzyłem, że jej cel jest szlachetny: uwolnić Azeroth od nieumarłych.$b$bAle gdy spędziłem trochę czasu w klasztorze na Polanach Tirisfal, zrozumiałem, że tracą kontakt z rzeczywistością. Teraz uważają, że każdy, kto nie nosi tabardu Krucjaty, jest zarażony. Niewinnych mężczyzn i kobiety torturowano, bo rzekomo dotknęła ich zaraza.$b$bSzkarłatna Krucjata musi zostać zmiażdżona w imię Światłości. Ty, $n, musisz zniszczyć ten obłąkany reżim.', 'Zabij nadinkwizytorkę Białowłosą, szkarłatnego komandora Mograine\'a, Heroda – Szkarłatnego czempiona – oraz tresera ogarów Lokseya, a potem złóż raport Raleighowi Pobożnemu w Południowym Brzegu.', '', 'Wróć do Raleigha Pobożnego w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(2480, 'koKR', '', 'Nigdy nie widziałem tak cudownych skutków trucizny! Mówisz, że Zanzil? Nigdy o nim nie słyszałem, ale muszę mu pogratulować tej mikstury.$B$BA więc mam cię z tego wyleczyć, a potem nauczyć, jak używać tej trucizny?$B$BDaj mi chwilę na zbadanie toksyny, $N.', 'Poczekaj, aż Serge Hinott skończy przygotowywać lek.', 'Lek gotowy', 'Porozmawiaj z Serge\'em Hinottem w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(2933, 'koKR', 'Butelki z jadem', 'W tych butelkach jest paskudny zielony jad.$B$BSądząc po liczbie butelek w tej wiosce, Suchokorzy muszą uważać go za bardzo ważny. Może aptekarz w pobliskim Smolnym Młynie chciałby dostać próbkę.', 'Zanieś butelkę z jadem aptekarzowi w Smolnym Młynie.', '', '', '', '', '', '', 0),
(2934, 'koKR', 'Nieuszkodzony gruczoł jadowy', 'Muszę mieć świeżą próbkę jadu, który mi $gprzyniosłeś:przyniosłaś;. Pająki, od których go zebrano, muszą żyć w Zaziemiu – poluj na nie, aż znajdziesz nieuszkodzony gruczoł jadowy, i przynieś mi go. Wiele pająków znajdziesz w pobliżu trollowego miasta Shadra\'Alor.$B$BNie zwlekaj, $N, bo gruczoł musi być świeży, gdy mi go dostarczysz.', 'Przynieś nieuszkodzony gruczoł jadowy aptekarzowi Lydonowi w Smolnym Młynie.', '', '', '', '', '', '', 0),
(6701, 'koKR', 'Emblematy Syndykatu', '', '', '', 'Odszukaj strażnika Krukowiska we Dworze Krukowiska w Międzygórzu.', '', '', '', '', 0),
(7321, 'koKR', 'Kojący krem z żółwia', 'Kto powiedział, że nieumarli nie znają się na gotowaniu? Weźmy na przykład mój sekretny przepis na krem z żółwia. Znałem ludzi, którzy wróciliby z zaświatów tylko po to, żeby zjeść miseczkę! He, he...$B$BSkoro o tym mowa, ostatnio nie mogłem go ugotować. Kiedyś sam chodziłem nad Jezioro Lordamere polować na kłapacze, paskudne bestie, ale nie mogę się oderwać od pracy tutaj.$B$BJeśli przyniesiesz mi trochę mięsa żółwia z kłapaczy, pokażę ci, jak to się robi!', 'Przynieś 10 kawałków mięsa żółwia Christophowi Jeffcoatowi w Smolnym Młynie.', '', 'Wróć do Christopha Jeffcoata w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(7645, 'koKR', 'Pasza dla koni wzbogacona manną', 'Srebrna Dłoń uznała mnie za SZALONĄ, kiedy powiedziałam, że potrafię zrobić specjalną paszę, która wykarmi duchowe konie. WSZYSCY uważali mnie za szaloną! Cóż, teraz przyszedł czas na rewanż!$B$BZrobię, czego potrzebujesz, $gPALADYNIE:PALADYNKO;... $gtak zwany CZEMPIONIE:tak zwana CZEMPIONKO;... ale to cię będzie kosztować. Do tej mieszanki potrzebuję specjalnych biszkoptów – wzbogaconych biszkoptów z manny, które sprzedaje tylko Argentowy Brzask. Żądam też, tak, ŻĄDAM złota jako rekompensaty za cierpienia, które zniosłam!$B$BPokaż mi to poświęcenie, którym tak się chełpisz, $gPALADYNIE:PALADYNKO;.', 'Zdobądź 20 wzbogaconych biszkoptów z manny – kluczowego składnika paszy dla koni wzbogaconej manną – dla Merideth Carlson w Południowym Brzegu w Międzygórzu. Wiadomo, że jedynym dostawcą biszkoptów jest Argentowy Brzask.$B$BMusisz jej też dać 50 sztuk złota, by ukoić jej zszargane nerwy.', '', 'Wróć do Merideth Carlson w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0),
(8322, 'koKR', 'Zgniłe jaja', 'Ludzie z Południowego Brzegu uwielbiają piwo, a najbardziej cenią to podawane w karczmie w Południowym Brzegu. Skoro ogarnął ich chaos Zaduszników, możemy to wykorzystać, żeby zepsuć im najnowszą partię trunków na całe tygodnie – jeśli nie miesiące!$B$BWeź te zgniłe jaja i włóż je do głównej beczki piwa w karczmie w Południowym Brzegu. Już sama twoja obecność wywoła zamieszanie, więc bądź $ggotów:gotowa; się bronić!$B$BGdy już dasz Południowemu Brzegowi posmakować czegoś, czego szybko nie zapomni, wróć do mnie tutaj, na festiwal!', 'Włóż zgniłe jaja do głównej beczki piwa w karczmie w Południowym Brzegu.', '', '', '', '', '', '', 0),
(8409, 'koKR', 'Zepsute beczki', 'Zgniłe jaja trafiły do beczki. Kolejne partie piwa z karczmy w Południowym Brzegu na pewno będą zepsute!$B$BTeraz wróć do przywoływaczki mroku Yanki na festiwalu Wiklinowego Człowieka na Polanach Tirisfal i zamelduj o sukcesie.', 'Wróć do przywoływaczki mroku Yanki na festiwalu Wiklinowego Człowieka na Polanach Tirisfal.', '', '', '', '', '', '', 0),
(9435, 'koKR', 'Zaginione kryształy', 'Jeśli istnieje jedna wielka prawda o Międzygórzu, to taka, że ten region jest skazany na życie w cieniu wojny. Nawet coś tak niewinnego jak wóz kamieni staje się celem.$B$BZwykle utrata materiałów budowlanych nie jest wielką stratą, ale ostatnia dostawa z Kopalni Lazurowej Żyły zawierała skrzynię rzadkich kryształów, które bardzo chciałem zbadać. Najeźdźcy Porzuconych przechwycili wóz i zabrali go na północny wschód, do wieży, którą próbują odbudować. Musimy koniecznie odzyskać te kryształy, $N!', 'Odbierz Porzuconym dostawę rzadkich kryształów i zwróć ją Huraanowi w Południowym Brzegu.', '', 'Wróć do Huraana w Południowym Brzegu w Międzygórzu.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(494, 'koKR', 'Kruczy krzyk z zachodu wzywa?$b$bZnakomite wieści! Międzygórze dojrzało do ataku. Możemy teraz wprowadzić w życie nasz plan zniszczenia. Varimathras będzie zadowolony.', 0),
(496, 'koKR', 'Te okazy są doskonałe. No cóż, $N, $gzdołałeś:zdołałaś; przynieść mi odrobinę radości w kolejny nędzny dzień. Doceniam twoje starania.', 0),
(498, 'koKR', 'Więc ludzie chcieli zrobić z naszych wojowników niewolników, tak? Jeszcze im pokażemy!$b$bWygląda na to, że Gol\'dira, naszego przywódcę, zabrali gdzie indziej. Musimy go odnaleźć i uwolnić. Ale na razie nie mamy pojęcia, gdzie jest...$b$bGdy tylko trafimy na jakiś trop, na pewno ci powiem, $N.', 0),
(499, 'koKR', 'Rech!', 0),
(500, 'koKR', 'Bardzo dobrze, $N. $GMusiałeś:Musiałaś; przerąbać się przez całą masę ogrów, żeby zebrać tyle kostek.$B$BTo powinno ich od nas odpędzić. Przynajmniej na jakiś czas.', 0),
(501, 'koKR', 'Znakomicie się $gspisałeś:spisałaś;, $N.', 0),
(502, 'koKR', 'Wylewasz trochę eliksiru na dłoń i podsuwasz ją Stanleyowi pod pysk.', 0),
(503, 'koKR', 'Dziękuję, $N. Poprowadziłem wyprawę z Durotaru na rozkaz wodza, ale jak widzisz, nasze plany nieco się posypały. Trzymali mnie tu w niewoli, w tej osadzie, i zmuszali do pracy: do dźwigania ciężarów, do kopania...$b$bTo, co wycierpiałem, nie ma jednak znaczenia. Mam ważne wieści, które musisz przekazać temu, kto teraz dowodzi naszą grupą.', 0),
(504, 'koKR', 'Bardzo dobrze. Oto twoja nagroda.$B$BA kiedy $gpolowałeś:polowałaś; na tych podżegaczy, jak wyglądało miasto Alterak? Pewnie jest w opłakanym stanie. Ogry nie słyną z czystości.$B$BNa szczęście dzięki twoim wysiłkom będą się trzymać z dala od Południowego Brzegu.', 0),
(505, 'koKR', 'Dziękuję, $N. Choć wciąż mogą się czaić w okolicy, mamy nadzieję, że niektórzy ze złodziei i zbójów, których $gzabiłeś:zabiłaś;, odpowiadają za śmierć poprzedniego sędziego. A nawet jeśli nie, Syndykat to skaza na tej ziemi i plama na honorze ludzkiej rasy.$B$BPołudniowy Brzeg przyjmuje ich śmierć z zadowoleniem.', 0),
(506, 'koKR', 'Co za tupet tych zadufanych ludzi! Pokażemy im, że orkowie nigdy nie ugną się przed ich wolą!$b$bTo będzie teraz nasza misja, obok odzyskania błyskotki, której pragnie wódz. Wygląda na to, że wypełniając jedno, osiągniemy i drugie.', 0),
(507, 'koKR', 'Nie, nie, proszę, nie rób mi krzywdy! Nigdy nie chciałam skrzywdzić twoich pobratymców, on trzymał mnie wbrew mojej woli! Proszę... oszczędź mnie!', 0),
(508, 'koKR', 'To dziwne, że wódz tyle poświęca dla tak drobnej rzeczy. Nie twierdzę, że go rozumiem, ale pójdę za nim, cokolwiek rozkaże. $GSpisałeś:Spisałaś; się dobrze, $N. Wódz z pewnością ucieszy się na wieść o twoim sukcesie.', 0),
(509, 'koKR', 'Ach, ten okropny smród kwiatów błotopyska. Przynajmniej do czegoś te plugawe gnole się nadają.', 0),
(510, 'koKR', '<Maleb czyta dokumenty.>$B$BTo bardzo niepokojące, $N. Na podstawie informacji z tych dokumentów i dotychczasowych poczynań Syndykatu musimy przyjąć, że ta banda rzezimieszków wypowiedziała Południowemu Brzegowi wojnę.', 0),
(511, 'koKR', 'Co to takiego? Chwileczkę... niech się przyjrzę.$B$B...$B$BHm, nigdy wcześniej nie widziałem takiego szyfru, choć muszę przyznać, że moja wiedza w tej dziedzinie bynajmniej nie jest pełna.', 0),
(512, 'koKR', 'Pozbawienie Syndykatu szlachty odbierze mu zdolność zdecydowanego działania i sprowadzi go do roli zwykłej bandy zbirów.$B$BDobrze służysz Przymierzu, $N.', 0),
(517, 'koKR', 'Nareszcie! Teraz możemy przystąpić do działania!', 0),
(518, 'koKR', 'Śnieg czerwieni się od krwi ogrów, ale nie możemy ustać w wysiłkach, dopóki duch i szeregi Kruszących Grań nie zostaną skruszone i wdeptane w ziemię i śnieg.', 0),
(519, 'koKR', '...a myślałam, że ogry i bez tego dość cuchną.$b$bGdy przyniesiesz mi głowę Mug\'Thola, każę zatknąć całą czwórkę na pikach nad Alterak. Stosowny pomnik dla tych, którzy sprzeciwiają się woli Mrocznej Pani.', 0),
(520, 'koKR', 'Dobrze $gwypełniłeś:wypełniłaś; swój obowiązek, $N. Głowa Mug\'Thola ozdobi najwyższy szczyt ruin Alterak, a strażnicy śmierci wdepczą resztki Kruszących Grań w ziemię.', 0),
(522, 'koKR', '<Maleb ogląda kontrakt.>$B$BTo wyjaśnia ostatni atak na Południowy Brzeg. Syndykat musi polować na mnie, tak jak na poprzedniego sędziego!', 0),
(523, 'koKR', 'Dziękuję, $N. Moja głowa spocznie nieco spokojniej, skoro ten łotr stracił swoją.', 0),
(524, 'koKR', 'Stawiasz skażoną beczkę na zakurzonym dywanie.', 0),
(527, 'koKR', 'Spocznij, $N. Widzę, że $gwróciłeś:wróciłaś; z bitwy. Moje źródła donoszą, że $gspisałeś:spisałaś; się dobrze na froncie w Międzygórzu.', 0),
(528, 'koKR', 'Śmierć coraz mocniej zaciska uchwyt wokół miasteczka Międzygórze. Bitwa idzie dobrze.', 0),
(529, 'koKR', 'Misja wykonana, $N. I to całkiem zręcznie, muszę dodać.', 0),
(532, 'koKR', 'Wieść o twoich chwalebnych czynach w Międzygórzu szybko się rozeszła. $GSpisałeś:Spisałaś; się dobrze, $N.', 0),
(533, 'koKR', 'Nareszcie wiemy, gdzie przetrzymują Gol\'dira. Ten obóz nie leży zbyt daleko stąd. Miejmy nadzieję, że nie będą tak dobrze przygotowani jak wtedy, gdy pojmali nas za pierwszym razem.', 0),
(536, 'koKR', 'Mam nadzieję, że to wystarczy, by przekonać Redpatha, że – ha! – wykonywałem jego rozkazy i uwalniałem Południowy Brzeg od straszliwej i okropnej groźby przerażających murloków! Bo nie ma większego zła niż spustoszenia siane przez przerośnięte ryby!', 0),
(537, 'koKR', 'Dobra robota, $N. Czuwanie Argusa to nie jest grupa, którą chcielibyśmy widzieć na czele Syndykatu.$B$BI choć być może $gzniszczyłeś:zniszczyłaś; ich tutejszego przywódcę, Nagaz był jedynie sługą kogoś innego. Wpływy Czuwania Argusa mogą sięgać w głąb całego kontynentu Azeroth.$B$BA nawet całego świata.', 0),
(539, 'koKR', 'Mroczna Pani będzie zadowolona, gdy się dowie, że ma nową kopalnię, dzięki której uzbroi swoich żołnierzy.', 0),
(541, 'koKR', 'Twoje czyny na polu bitwy zasługują na najwyższą pochwałę.', 0),
(544, 'koKR', '$GOddałeś:Oddałaś; Porzuconym wielką przysługę, $N. Bardzo brakowało nam tych artefaktów.$b$bDobrze też słyszeć, że Kegana i pozostałych zdrajców spotkała sprawiedliwość.', 0),
(545, 'koKR', 'Bardzo dobrze. Te ruiny powinny być teraz na tyle bezpieczne, by je przeszukać, jeśli zachowa się ostrożność.$B$BDziękuję, $N.', 0),
(546, 'koKR', 'Cenne czaszki! Jakie piękne! Tak jak obiecałem, należy ci się nagroda, $N!', 0),
(547, 'koKR', '$GZnalazłeś:Znalazłaś; go!$b$bAch, z moim ukochanym mieczem w dłoni znów czuję się kompletny. Wielkie dzięki!', 0),
(549, 'koKR', 'Znakomicie, $N. W tym tempie ta ziemia w mig pozbędzie się szkodników z Syndykatu.', 0),
(550, 'koKR', 'A więc to o tobie tyle słychać, $N? To ty $gzadałeś:zadałaś; tak decydujący cios siłom Przymierza w Międzygórzu? Wieść o twoich chwalebnych czynach szybko dotarła do Podmiasta.$b$bCzeka cię wielka przyszłość w szeregach Mrocznej Pani, jeśli nadal będziesz się wykazywać takim przywództwem i biegłością w boju.$b$bChoć naszym głównym zagrożeniem jest armia Plagi Króla Lisza nadciągająca z północy, ludzki „problem” wciąż krzyżuje nasze plany wojenne. Ty jednak $gpokazałeś:pokazałaś;, że ludzie mogą upaść i upadną.', 0),
(551, 'koKR', 'Kolejne zaszyfrowane notatki?$B$BChciałbym mieć talent, by rozszyfrować wszystkie te dziwne skrawki pisma, które docierają do nas z Alterak. Obawiam się jednak, że brak mi wiedzy.', 0),
(552, 'koKR', '$GZnalazłeś:Znalazłaś; ją! Znakomicie, $N!', 0),
(553, 'koKR', 'Z głębi ziemi dobywa się potężny łoskot.', 0),
(555, 'koKR', 'Wszyscy będą zachwyceni: kojący krem z żółwia kucharza Jessena znów jest w menu!', 0),
(556, 'koKR', 'Nadadzą się doskonale. Choć wygląda na to, że ich magia wygasła, najlepiej będzie, jeśli pierwsze eksperymenty maga zostaną przeprowadzone na obojętnych okazach takich jak te.$b$bDziękuję, $N.', 0),
(557, 'koKR', '$GZnalazłeś:Znalazłaś; je. Mam nadzieję, że żywiołaki, którym $gzdjąłeś:zdjęłaś; te karwasze, były skłonne do współpracy?$b$bHm... zdaje się, że śmierć nie tylko zatrzymała mi serce, ale i odebrała wyczucie komediowego rytmu.$b$bCóż, dziękuję, $N. Dobrze służysz magowi, a tym samym Mrocznej Pani.', 0),
(559, 'koKR', 'Na miłość Światłości... przecież z nich cieknie na ziemię.$b$bJa tam nie znoszę dotykać tych paskudztw. Ryby są w porządku, ale kiedy wyrastają im nogi i zaczynają łazić... Mówię ci, od tygodni nie tknąłem ryby, a w Południowym Brzegu to znaczy, że prawie nic się nie je.', 0),
(560, 'koKR', '$GChłopiec:Dziewczyna; na posyłki Farrena, tak?$b$bJeśli $gpomogłeś:pomogłaś; Farrenowi zdobyć te głowy, to dziękuję. Południowy Brzeg potrzebuje pracowitych rąk i wysiłku, by utrzymać swoją obronę.', 0),
(561, 'koKR', 'Nagi, co? Redpath musiał dostać te same wieści co ja... Ha! Nie dostanie awansu dzięki mojej harówce. Pozwól, że wyjaśnię.', 0),
(562, 'koKR', 'Skoro nagi w Południowym Brzegu zostały rozgromione, przeniesienie mam jak w banku. Znów zobaczę Wichrogród... i wyrwę się z tego zapomnianego przez Światłość portu.', 0),
(564, 'koKR', 'No to ci dopiero wieści! Trzeba było od pierwszego dnia poszukać porządnego wojaka, żeby się zajął tymi bestiami. Twój staruszek byłby z ciebie dumny, $N.', 0),
(565, 'koKR', 'Nadszedł czas, by wielki Bartolo zaczął czarować! Nie potrzebuję ani laski czarodzieja, ani żadnej różdżki. Bo ja, wielki Bartolo, czaruję zwykłą igłą i nicią!', 0),
(566, 'koKR', 'Owocnie pracujesz, $N. Po śmierci barona Vardusa przywódców Syndykatu jest coraz mniej. Ich opór i naprzykrzanie się nam nie potrwają długo.', 0),
(567, 'koKR', '$GPrawdziwy z ciebie łowca:Prawdziwa z ciebie łowczyni; nagród, $N. Dobra robota.', 0),
(657, 'koKR', 'Jeśli to przyniesie Phinowi spokój, osobiście zniszczę każdego Porzuconego co do jednego. Tyle dla nas zrobił od czasu zarazy. Nie sądziliśmy, że jeszcze kiedyś znajdziemy przyjaciół czy rodzinę.$B$BGdy będziesz $ggotów:gotowa;, daj mi znać. Zaczniemy od razu.', 0),
(658, 'koKR', 'Doskonale!$B$BZobaczmy, o co tu chodzi...', 0),
(659, 'koKR', 'Staraj się być jak najciszej, $gwędrowcze:wędrowniczko;.$B$BOrkowie nie lubią, gdy ktoś ich szpieguje, a z tą farmą jest coś więcej na rzeczy, niż się wydaje.', 0),
(660, 'koKR', '$GOddałeś:Oddałaś; nam wielką przysługę, $N. Dziękuję.$B$BMam nadzieję, że Kin nie sprawiała tam na dole zbyt wielu kłopotów. Jest bardzo przyjazna, ale potrafi być równie zabójcza, gdy jest się jej wrogiem.', 0),
(661, 'koKR', 'A więc te dwie łobuziary jednak mają się dobrze? Haha, cieszę się, że to słyszę. Dziękuję, że $gprzyniosłeś:przyniosłaś; mi wieści o tym, gdzie są i jak się mają – bardzo mnie cieszy, że wciąż żyją. Obie są niezastąpione jako przyjaciółki i towarzyszki podróży.$B$BAle... ważniejsze, żebym ci należycie podziękował za pomoc. Proszę. Weź to wraz z podziękowaniami od mojej drużyny.$B$BJeśli dopisze nam szczęście, dowiemy się, co knują Porzuceni, i położymy temu kres.', 0),
(676, 'koKR', 'A więc myślisz, że $gjesteś dość silny:jesteś dość silna;, by pomóc Młotogrodowi? Niech będzie.$b$bTallow albo wysłał cię do tego kopca ogrów w nadziei, że zginiesz, albo uważa, że $gjesteś dość silny:jesteś dość silna;, by nam pomóc. Tak czy inaczej, już tu jesteś, a ja potrzebuję więcej żołnierzy do walki z nieustannymi atakami.$b$bJeśli zamierzasz zostać w Młotogrodzie, to odpocznij i porozmawiaj ze mną znowu, gdy będziesz $ggotów:gotowa;. Walki tu nie brakuje.', 0),
(1051, 'koKR', 'Vorrel wiódł tak udręczone istnienie. A jakim był dobrym towarzyszem...$b$bPrzeklęci, plugawi ludzie!$b$bVorrela już nie ma i nigdy więcej nie zazna nieżycia. Przynajmniej mogę znaleźć pocieszenie w zemście, której $gdokonałeś:dokonałaś; w jego imieniu. Za to ci dziękuję.$b$bA teraz zostaw mnie, bym mogła go opłakiwać...', 0),
(1052, 'koKR', 'Brat Anton wciąż głosi słowo Szkarłatnej Krucjaty? Ojej...', 0),
(1053, 'koKR', 'Choć uczniowie Światłości nigdy nie radują się z utraty życia, musimy pogodzić się z tym, że czasem takie ofiary są konieczne dla większego dobra królestwa i świata.$B$BSwoimi czynami w klasztorze $gocaliłeś:ocaliłaś; wiele niewinnych istnień, $N. Pochwalam twoją wytrwałość.', 0),
(2480, 'koKR', 'Lek jest gotowy! Wypij tę antytoksynę, a pełzające szaleństwo ustąpi. Z zapachem jednak nic nie poradzę.', 0),
(2933, 'koKR', 'Ach, a cóż to takiego? Wygląda na jad... jakiegoś pajęczaka, jak mniemam. A skąd go $gwziąłeś:wzięłaś;?', 0),
(2934, 'koKR', 'Och, wspaniale! Jad jest całkiem świeży i jestem pewien, że bardzo zabójczy. Dziękuję!', 0),
(6701, 'koKR', 'Hej, niezła robota! Tak dalej, a inni łotrzy może przestaną na ciebie pluć.', 0),
(7321, 'koKR', 'Mój kojący krem z żółwia rozgrzeje cię w chłodną noc... jeśli ci na takich rzeczach zależy.', 0),
(7645, 'koKR', 'TAK, A TERAZ KTO – chwila – dajesz mi też złoto? To nie ty $gnazwałeś:nazwałaś; mnie szaloną (tak naprawdę nazwali mnie świrniętą wariatką)... a jednak jesteś $ggotów:gotowa; do poświęceń nawet za krzywdy, których nie $gwyrządziłeś:wyrządziłaś;?$B$BJa... źle cię oceniłam, $N. Jeśli będziesz potrzebować więcej paszy, przyjdź do mnie. Dam ci ją za darmo. Dziękuję... $gszlachetny:szlachetna; $N.$B$BAle pieniądze i tak zatrzymam – aż tak mi nie odbiło, żeby oddawać fortunę.', 0),
(8322, 'koKR', 'Beczka jest pełna piwa.$B$BPrzebiwszy się do wnętrza karczmy, wkładasz jaja do beczki. Czujesz, jak w powietrzu rozchodzi się ohydny smród...', 0),
(8409, 'koKR', 'Ach, sukces! $GPokazałeś:Pokazałaś; prawdziwego ducha Zaduszników – ducha PORZUCONYCH, powinnam powiedzieć!$B$B<Przywoływaczka mroku Yanka śmieje się i zaciera ręce.>$B$BUpajam się myślą, że Południowy Brzeg musi teraz ucztować przy kiepskim piwie albo obyć się bez niego! A ty weź te smakołyki. Wierzę, że zrobisz z nich dobry użytek!', 0),
(9435, 'koKR', 'Dzięki Światłości! Z tonu listu brygadzisty wynikało, że w tej skrzyni były jedyne znane próbki z kopalni. Gdybyśmy je stracili, $N, być może nigdy nie zobaczylibyśmy podobnych.$B$BNie wiem, jak ci dziękować za pomoc.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(496, 'koKR', 'Widzę, że $gwróciłeś:wróciłaś;. Mam nadzieję, że $gzdołałeś:zdołałaś; zebrać potrzebne mi składniki. Kolejny dzień bez śmierci wprawi mnie w okropnie ponury nastrój.', 0),
(498, 'koKR', 'Musisz się pospieszyć, $N. Drżę na myśl, co ludzie mogą robić Drullowi i Tog\'tharowi.', 0),
(499, 'koKR', 'Kum!', 0),
(500, 'koKR', '$N, wciąż polujesz na ogry? Masz kostki, które kazałem ci zebrać?', 0),
(501, 'koKR', 'Pamiętam cię, $N. $GMiałeś:Miałaś; mi pomóc w przyrządzeniu mojego najnowszego eliksiru. Potrzebuję tej krwi, zanim sprowadzę na mieszkańców Międzygórza moją własną, szczególną odmianę niedoli.', 0),
(502, 'koKR', 'Hau?', 0),
(503, 'koKR', 'Daj mi klucz, $N. Sam otworzę zamek.', 0),
(504, 'koKR', 'Masz jeszcze podżegaczy do zabicia, $N. $GPowinieneś:Powinnaś; być w górach i wykonywać zadanie, a nie siedzieć tu na dole ze schowaną bronią.', 0),
(505, 'koKR', 'Ufam, że $gzabiłeś:zabiłaś; tych zbirów z Syndykatu?', 0),
(507, 'koKR', 'C-czego chcesz?', 0),
(508, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Masz dobre wieści?', 0),
(509, 'koKR', 'Jak ci poszło w Zagrodzie Nethandera?', 0),
(510, 'koKR', '$N, wyglądasz na $gzaniepokojonego:zaniepokojoną;. Chcesz mi coś powiedzieć?', 0),
(511, 'koKR', 'Słucham, $gpanie:pani;? Masz do mnie jakąś sprawę?', 0),
(512, 'koKR', '$GPolowałeś:Polowałaś; na Syndykat? Masz te sygnety?', 0),
(517, 'koKR', 'Czasem tak się tu nudzę w Smolnym Młynie, że otwieram słój z formaldehydem i pozwalam, by ten cudowny aromat rozszedł się w powietrzu. Choć Umpi trochę się wtedy denerwuje.$b$bUdało ci się zdobyć beczkę od krasnoludów? Przysięgam, jeśli przez kolejny dzień będę się gapił na ten zabójczy eliksir, nie mogąc go na nikim użyć, zacznę krzyczeć.', 0),
(519, 'koKR', 'Chcę ich głów, $N, a nie wymówek.', 0),
(520, 'koKR', 'Trzy głowy już mam, czwartej potrzebuję. Będzie to głowa Mug\'Thola albo twoja, $N. To ci obiecuję.', 0),
(522, 'koKR', 'Wyglądasz na $gzdyszanego:zdyszaną;! Masz coś do zameldowania?', 0),
(523, 'koKR', 'Baron Vardus nie może sądzić, że Południowy Brzeg pozwoli mu bezkarnie nasyłać na nas swoich zbirów. Chcę jego głowy!', 0),
(524, 'koKR', 'Od dywanu bije zapach stęchlizny.', 0),
(527, 'koKR', 'Jako najwyższa egzekutorka Smolnego Młyna podlegam bezpośrednio Varimathrasowi i Mrocznej Pani, a ty masz obowiązek wykonywać moje rozkazy.$B$BMoże traktujesz tę wojnę z Przymierzem zbyt lekko? Jeśli tak, powinnam ściąć cię tu i teraz. W przeciwnym razie udaj się na zachód, do miasteczka Międzygórze, i walcz z ludźmi, jak ci rozkazano.$B$BOdmaszerować.', 0),
(528, 'koKR', 'Masz swoje rozkazy, $N. Przestań się tu ociągać w Smolnym Młynie, skoro gdzie indziej czeka robota.', 0),
(529, 'koKR', 'Udało ci się wykonać rozkazy, $N? $GPozbyłeś:Pozbyłaś; się Verringtana i jego pomocników? I gdzie ta dostawa żelaza?', 0),
(532, 'koKR', 'Jakie przynosisz wieści?', 0),
(533, 'koKR', '$GZnalazłeś:Znalazłaś; coś? Obawiam się, że szanse Gol\'dira maleją z dnia na dzień...', 0),
(536, 'koKR', 'Jeszcze jedno piwo, proszę, poprzednie jakby wyparowało!$B$BŚwiatłości, jak długo jeszcze będę tu tkwił?$B$BO, to ty, $N. $GZabiłeś:Zabiłaś; już te murloki?', 0),
(537, 'koKR', '$GZnalazłeś:Znalazłaś; wysłanników Czuwania Argusa?', 0),
(539, 'koKR', '$GOtrzymałeś:Otrzymałaś; bezpośredni rozkaz ataku na Kopalnię Lazurowej Żyły. Obyś $gmiał:miała; dobre powody, by obijać się w Smolnym Młynie, bo inaczej zetnę cię za zdradę.', 0),
(541, 'koKR', 'Dun Garok okazuje się dla ciebie zbyt wielką przeszkodą, $N? A sądziłam, że tak dzielnie $gzaznaczyłeś:zaznaczyłaś; swoją obecność w Międzygórzu.$B$BJeśli nie podołasz przydzielonej ci misji, znajdę kogoś, kto osiągnie lepsze wyniki. A co do ciebie... cóż, jestem pewna, że Mroczna Pani zawsze znajdzie zajęcie dla kolejnych grabarzy na Polanach Tirisfal.', 0),
(544, 'koKR', '$GZnalazłeś:Znalazłaś; złodziei? A co ważniejsze, $gznalazłeś:znalazłaś; to, co ukradli?', 0),
(545, 'koKR', '$GPrzerzedziłeś:Przerzedziłaś; już dalarańskie patrole wokół ich ruin?', 0),
(546, 'koKR', 'Czyżby $N, $gten szczęściarz:ta szczęściara;, $gwrócił:wróciła;? Ilu ludzi dziś $gzarżnąłeś:zarżnęłaś;? Mam nadzieję, że setki!$b$bMasz dla mnie jakieś czaszki?', 0),
(547, 'koKR', 'Udało ci się odzyskać mój miecz, $N? Najwyższa egzekutorka Darthalia powiesi mnie na krokwiach, jeśli dowie się o mojej głupocie.', 0),
(549, 'koKR', 'Nie masz nic lepszego do roboty niż sterczeć tu przede mną, $N? Jako najwyższa egzekutorka mam pilniejsze sprawy niż gapienie się na twoje gnijące oblicze.', 0),
(550, 'koKR', 'Co sprowadza cię z pola bitwy aż do Podmiasta?', 0),
(551, 'koKR', 'Och. Chcesz, żebym na coś rzucił okiem? Mam nadzieję, że to jakiś okruch wiedzy zebrany wysoko w górach...', 0),
(552, 'koKR', '$GOdzyskałeś:Odzyskałaś; już różdżkę Helculara? W tej okolicy jest tyle yeti, że trudno będzie ją znaleźć. Ale musimy ją mieć, żeby działać dalej.', 0),
(553, 'koKR', 'Grób Helculara aż kipi mistyczną energią.', 0),
(555, 'koKR', 'Udało się znaleźć składniki? Powiem ci, ta okolica nie jest już tak spokojna jak kiedyś. Ach, gdyby tylko nigdy nie doszło do tych niepokojów...', 0),
(556, 'koKR', 'Masz wytarte kamienne żetony, $N? Mag nie może się doczekać, by poznać ich tajemnice.', 0),
(557, 'koKR', 'Witaj, $N. Żywiołaki to trudna zwierzyna, ale wiem, że podołasz. Masz te karwasze więzi?', 0),
(559, 'koKR', '$GZdobyłeś:Zdobyłaś; dla mnie te głowy, $N?', 0),
(560, 'koKR', 'Witaj, $gobywatelu:obywatelko;. $GPrzyszedłeś:Przyszłaś; użyczyć swego ramienia, by strzec bezpieczeństwa Południowego Brzegu?', 0),
(562, 'koKR', 'Mam gotowy list do majora Samuelsona w Wichrogrodzie. Brakuje mi tylko wyników.', 0),
(564, 'koKR', 'Lwy górskie wybijają nam konie na prawo i lewo, a ty tu chcesz trajkotać o pogodzie i innych duperelach.$B$BTrzeba mi znaleźć prawdziwego bohatera. Więcej zabijania, mniej gadania.', 0),
(565, 'koKR', 'A więc $gwróciłeś:wróciłaś; do wielkiego Bartola. Może $gzebrałeś:zebrałaś; już materiały potrzebne do twojego płaszcza z futra yeti? A może po prostu lubisz pławić się w blasku mojej wielkości – wielkości Bartola!', 0),
(566, 'koKR', 'Ach, $N. Może $gprzyszedłeś:przyszłaś; odebrać nagrodę za głowę barona Vardusa?', 0),
(658, 'koKR', 'Doceniamy twoją pomoc w szukaniu tego kuriera, $N.$B$BPod twoją nieobecność Kin widziała aptekarza wychodzącego z tego samego domu na południe stąd. Jestem pewna, że knują coś złego – potrzebuję tylko dowodu, zanim zrobimy coś pochopnego.$B$BUdało ci się już coś znaleźć?', 0),
(660, 'koKR', 'Czas na gadanie minął. Chroń Kinelory, jeśli choć trochę zależy ci na mieszkańcach Międzygórza.', 0),
(676, 'koKR', 'Nie mam czasu nawet naostrzyć topora, a co dopiero opuścić placówkę, by zabić te bestie, które chcą wybić moich pobratymców.$B$BNie wyglądasz na kogoś, kto ma doświadczenie siepacza, a co dopiero prawdziwego wojownika. Czego chcesz, $N?', 0),
(1051, 'koKR', 'Czego chcesz, $gnieznajomy:nieznajoma;?', 0),
(1052, 'koKR', 'Kto idzie? Czego ode mnie chcesz?', 0),
(1053, 'koKR', 'Zepsucie w klasztorze nie ustanie, dopóki nie zostaną usunięci najwyżsi rangą dostojnicy.$b$bW imię Światłości zabij nadinkwizytorkę Białowłosą, szkarłatnego komandora Mograine\'a, Heroda – Szkarłatnego czempiona – oraz tresera ogarów Lokseya. Gdy padną, być może prawdziwa sprawa znów rozgorzeje. Do tego czasu każdy, kto stanie na drodze Krucjaty, jest w niebezpieczeństwie.$b$bWyrusz z Południowego Brzegu i dopilnuj tego!', 0),
(2933, 'koKR', 'Witaj, $gszlachetny:szlachetna; $N. Dzień był długi i ani jeden eksperyment się nie powiódł... Mam nadzieję, że przynosisz mi dobre wieści.', 0),
(2934, 'koKR', 'Masz nieuszkodzony gruczoł jadowy, $N? Nie mogę się doczekać eksperymentów z jego świeżym jadem, a już zamówiłem gromadkę małych, strasznie słodkich zwierzątek, na których go wypróbuję!', 0),
(6701, 'koKR', 'Od lat toczymy zażartą walkę z Syndykatem. Czego brakuje im w umiejętnościach, nadrabiają liczebnością. Nie da się ich wybijać na tyle szybko, żeby wyraźnie przerzedzić ich szeregi!$B$BPrzekonaliśmy się, że najlepszym sposobem na ich liczebność jest podkradanie im emblematów. Gdy emblemat zostaje skradziony, okryty hańbą członek jest „załatwiany” we własnym gronie.$B$BOczyść ich kieszenie do czysta i oddawaj emblematy mnie albo któremuś z pozostałych strażników.$B$BZacznij od Twierdzy Durnhold, na południe stąd.', 0),
(7321, 'koKR', 'Udało się znaleźć składniki? Powiem ci, że tych robali z Przymierza jest teraz w okolicy stanowczo za dużo... Moim zdaniem i tak podeszli już o wiele za blisko...', 0),
(7645, 'koKR', 'Tak, udowodniłam teraz, że się $gmyliłeś:myliłaś;, prawda? Udowodniłam, że wszyscy się mylili! PRZEZ CAŁY CZAS MIAŁAM RACJĘ!!!', 0),
(9435, 'koKR', '$GZdołałeś:Zdołałaś; odzyskać kryształy od Porzuconych?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(2263, 0, 'koKR', 'Mam nadzieję, że $gprzyszedłeś:przyszłaś; tu pracować, $N. Mamy mnóstwo roboty, a Horda, Syndykat i ogry nam w tym nie pomogą.', 0);
