INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(249, 'koKR', 'Valiku, pilnuj niewolnika do naszego powrotu. Trzymanie GO tutaj nie jest już bezpieczne. Przeniesiemy go na północ, dalej od wszelkich ciekawskich oczu. To zwierzęta, ale zwierzęta brutalne – gdyby zebrało się ich dość, mielibyśmy powody do niepokoju. Lepiej ukryć wszelkie ślady, które mogłyby ich sprowokować. Ostatnie, czego chcemy, to dać im powód, by się zebrali i uderzyli na nas całą siłą. ', 0),
(261, 'koKR', 'Rejestr miejski Międzygórza My, mieszkańcy Międzygórza, uroczyście przysięgamy wiarę i oddanie Przymierzu, na którego straży stoją wielcy monarchowie: król Magni Miedziobrody z Żelaznej Kuźni i król Anduin Wrynn z Wichrogrodu. Oto rejestr miejski służący zarządzaniu tym pięknym miastem u podnóża wielkich Gór Alterak oraz ewidencji tych, którzy zapłacili podatki swoim królom i wielkiemu, wszechmocnemu Przymierzu. ', 0),
(262, 'koKR', 'Sędzia Rutherford Burnside Wszystkie długi uregulowane. Kowal Avery Verringtan Wszystkie długi uregulowane. Urzędnik Horrace Białorumak Wszystkie długi uregulowane. Rajca Gillis Wszystkie długi uregulowane. Rajca Hooks Wszystkie długi uregulowane. Rolnik Getz Wszystkie długi uregulowane. Rolnik Ray Dług niespłacony. Obiecał zapłatę płodami rolnymi w czasie żniw. Rolnik Lyion Dług niespłacony. Eksmitowany z ziemi. ', 0),
(263, 'koKR', 'Rolniczka Kalaba Długi niespłacone. Obiecała zapłatę płodami rolnymi w czasie żniw. Obywatel Wilkes Wszystkie długi spłacone. Obywatel Bonoan Wszystkie długi spłacone. Górnik Wellty Dług niespłacony. Zapłata przy następnej dostawie rudy z Lazurowej Żyły. Górnik Sidney Dług niespłacony. Zapłata przy następnej dostawie rudy z Lazurowej Żyły. Górnik Hackett Dług niespłacony. Zapłata przy następnej dostawie rudy z Lazurowej Żyły. ', 0),
(265, 'koKR', 'Górnik Orwell Dług niespłacony. Zapłata przy następnej dostawie rudy z Lazurowej Żyły. Górnik Fitzgerald Dług niespłacony. Zapłata przy następnej dostawie rudy z Lazurowej Żyły. Obywatel Netherand Wszystkie długi spłacone. Obywatel May Wszystkie długi spłacone. Brygadzista Bonds Dług niespłacony. Zapłata przy następnej dostawie rudy z Lazurowej Żyły. ', 0),
(371, 'koKR', 'L. F. rozkazał wzmóc ataki na głupców z Przymierza. Poniżej lista materiałów potrzebnych do ważnej misji przeciwko Południowemu Brzegowi:$B$BRacje podróżne na tydzień dla 20 ludzi$B20 czarnych strojów nocnych$B20 par nowych butów$B25 nowych mieczy$B30 noży do rzucania$B20 czarnych masek$B10 fiolek łatwopalnego oleju$B50 dawek paraliżującej trucizny$B5 skradzionych mundurów straży Południowego Brzegu, jeśli się da$B100 srebrnych monet$B$B--Baron V.$BKwatermistrz', 0),
(2217, 'koKR', 'Ku pamięci Jessego Moralesa', 0),
(2858, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">\nAnthony Ray Stark\n</H1>\n<H2 align="center">\n1961 - 2005\n</H2>\n</BODY>\n</HTML>', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(2435, 5, 0, 'koKR', 'Herold Południowego Brzegu umiera.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(559, 'koKR', '%s ciężko się zatacza.', '', 0),
(560, 'koKR', '%s mamrocze coś bez ładu i składu.', '', 0),
(561, 'koKR', '%s podnosi kufel do oka i marszczy brwi.', '', 0),
(579, 'koKR', 'Kum!', '', 0),
(580, 'koKR', '%s obwąchuje eliksir, po czym łapczywie się do niego zabiera!', '', 0),
(581, 'koKR', 'Wreszcie okazują litość! Dali nam coś do picia!', '', 0),
(582, 'koKR', 'I to jeszcze stout Shindiggera! Dzięki Światłości! Umierałem z pragnienia!', '', 0),
(592, 'koKR', 'Ach, jak dobrze być wolnym od więzów! $GUwolniłeś:Uwolniłaś; już Tog\'thara? Ludzie rozdzielili nas po tym, jak nas pojmali.', '', 0),
(593, 'koKR', '$GUwolniłeś:Uwolniłaś; już Drulla? Nie wiem, gdzie go trzymają.', '', 0),
(594, 'koKR', 'Idź przodem beze mnie! Sam dotrę do Smolnego Młyna.', '', 0),
(595, 'koKR', 'Będę cię tylko spowalniał, ale żaden różowoskóry człowiek nie odbierze mi wolności!', '', 0),
(598, 'koKR', 'Tutaj! W środku pokoju. $GZnalazłeś:Znalazłaś; klucz do moich łańcuchów? Ma go człowiek o imieniu Borhuin.', '', 0),
(614, 'koKR', 'Moje drzewa... uschły i umarły, tak jak ja.', '', 0),
(615, 'koKR', 'Ten sad jest teraz równie jałowy i martwy jak moja gnijąca skorupa. Kiedyś te drzewa obsypywały się owocami, a teraz jest tu tylko zgnilizna.', '', 0),
(616, 'koKR', 'Całe życie opiekowałem się tymi drzewami. Przycinałem je i pielęgnowałem... to tylko sprawiedliwe, że dołączyły do mnie w śmierci.', '', 0),
(619, 'koKR', 'Pomocy! Na pomoc! Zabójcy na wzgórzach! Do broni! Do broni!', '', 0),
(620, 'koKR', 'Słuchajcie! Słuchajcie! *dyszy* Strzeżcie się, mieszkańcy Południowego Brzegu: zabójcy zmierzają do naszego pięknego miasta!', '', 0),
(621, 'koKR', 'Straże na posterunki! Pewnie znów chodzi im o sędziego. Trzeba go chronić! Mogą nadejść z każdej strony!', '', 0),
(623, 'koKR', 'Herold Południowego Brzegu chwyta się za kark, a jego oczy rozszerzają się.', '', 0),
(626, 'koKR', 'Zabójcy... ratujcie... sę... dzieee...', '', 0),
(741, 'koKR', '%s zaczyna przywoływać posiłki!', '%s zaczyna przywoływać posiłki!', 0),
(757, 'koKR', '%s zaczyna pękać i się rozpadać.', '', 0),
(758, 'koKR', '%s słabnie, gdy odpadają od niego bryły skały.', '', 0),
(759, 'koKR', '%s rozpada się w gruz, ale wciąż walczy.', '', 0),
(789, 'koKR', 'Mam dość tych bzdur! Szykuj się na śmierć!', 'Mam dość tych bzdur! Szykuj się na śmierć!', 0),
(816, 'koKR', '', 'No to zaczynajmy. Im dłużej tu jesteśmy, tym więcej szkód nieumarli mogą wyrządzić w Międzygórzu.', 0),
(817, 'koKR', '', 'Dobra, tu naprawdę musimy mieć oczy dookoła głowy. Bądź $ggotów:gotowa;!', 0),
(818, 'koKR', '', 'Pilnuj moich pleców! Zobaczę, co da się znaleźć w tych gratach...', 0),
(819, 'koKR', '', '%s zaczyna przetrząsać rzeczy aptekarza.', 0),
(820, 'koKR', '', 'Coś znalazłam... chyba.', 0),
(821, 'koKR', '', 'Założę się, że Quae uzna to za ważne. Dużo wie o takich rzeczach – żadna z niej ekspertka, ale sporo wie.', 0),
(822, 'koKR', '', 'No dobra, zmywajmy się stąd, szybko, szybko! Postaraj się nadążyć. Zamierzam dać nogę.', 0),
(891, 'koKR', '', '%s wręcza swój tobołek Quae.', 0),
(892, 'koKR', '', 'Udało się! Quae, udało się!', 0),
(897, 'koKR', '', 'Atakuj mnie, jeśli chcesz, ale nie powstrzymasz mnie przed powrotem do Quae.', 0),
(1376, 'koKR', 'Wreszcie. Ten potwór dostał to, na co zasłużył.', '', 0),
(1377, 'koKR', '%s łamie pieczęć na liście Antona i zaczyna go czytać.', '', 0),
(1378, 'koKR', 'Na Światłość! To niedobrze. Czegoś nie rozumiesz, $n.', '', 0),
(1379, 'koKR', '%s rzuca list Antona na stół.', '', 0),
(2742, 'koKR', 'Drwisz ze mnie, gdy nie mogę się bronić, przykuty do tej żelaznej kuli?', '', 0),
(2744, 'koKR', 'Jeden z ludzi ma klucz do tego piekielnego ustrojstwa. Chyba mówili, że nazywa się Eston.', '', 0),
(2745, 'koKR', 'Odejdź stąd, $N, bo i ciebie zakują w łańcuchy.', '', 0),
(2746, 'koKR', 'Gdzie jest klucz do tej kłódki?', 'Gdzie jest klucz do tej kłódki?', 0),
(2747, 'koKR', 'Marlgen... Jeden z kluczników. Ma klucz do moich okowów.', '', 0),
(8200, 'koKR', 'Trochę tu wieje... ale co mnie to obchodzi? Jestem martwy.', '', 0),
(8478, 'koKR', 'Uważaj na siebie, $gnieznajomy:nieznajoma;.', '', 0),
(8479, 'koKR', 'Dwór Krukowiska cię nie zna, $N.', '', 0),
(8480, 'koKR', 'Zuchwałość. Mistrz Krukowiska nie lubi zuchwałości.', '', 0),
(8481, 'koKR', 'Dobrze cię znów widzieć, $n.', '', 0),
(8482, 'koKR', 'Witaj, $N. $GRozmawiałeś:Rozmawiałaś; już z Fahradem?', '', 0),
(8483, 'koKR', 'Syndykat to banda partaczy – niezorganizowanych, nieudolnych i leniwych...', '', 0),
(8484, 'koKR', 'Naprawdę $gstałeś:stałaś; się bardziej $gprzebiegły:przebiegła;, $n.', '', 0),
(8485, 'koKR', 'To zaszczyt znów cię widzieć, $n.', '', 0),
(8486, 'koKR', 'Zdaje się, że Simone cię wcześniej szukała, $n. $GRozmawiałeś:Rozmawiałaś; już z nią?', '', 0),
(11865, 'koKR', 'Mogę ci pokazać, co mam na sprzedaż?\n', '', 0),
(48868, 'koKR', 'Derak Zmrok, do usług!', '', 0),
(50624, 'koKR', 'Cieszymy się, że nam pomagasz.', '', 0);
